def _get_path(path):
    if path.endswith('.ipynb'):
        path = path[:-6]
    if path.endswith('.ipynb.py'):
        path = path[:-9]
    if path.endswith('.ipynb.pyc'):
        path = path[:-10]
    if path.endswith('.ipynb.pyo'):
        path = path[:-10]
    if path.endswith('.ipynb.pyd'):
        path = path[:-10]
    return path


def _get_cell(path):
    if path.endswith('.py'):
        path = path[:-3]
    if path.endswith('.pyc'):
        path = path[:-4]
    if path.endswith('.pyo'):
        path = path[:-4]
    if path.endswith('.pyd'):
        path = path[:-4]
    if path.endswith('.pyw'):
        path = path[:-4]
    if path.endswith('.ipynb'):
        path = path[:-6]
    if path.endswith('.ipynb.py'):
        path = path[:-9]
    return path


def _get_cell_name(path):
    return _get_cell(path).split('/')[-1]


def _get_cell_path(path):
